// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount, address recipient) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(recipient) {} catch {}
        uint256 balanceAfter = address(c).balance;
        bool isOwner = (caller == address(this));
        if (isOwner) {
            assertTrue(balanceAfter == 0);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
